// 平均点が低く出るバグ(off-by-one)を再現する
// ここを変えてみよう:int i = 1 を int i = 0 に直して再実行する
static double average(int[] a) {
    int sum = 0;
    for (int i = 1; i < a.length; i++) {
        sum += a[i];
        // デバッガなら Variables ビューで見える値
        System.out.println("i=" + i + " a[i]=" + a[i]
                + " sum=" + sum);
    }
    return (double) sum / a.length;
}

int[] scores = {80, 90, 70};
System.out.println("平均: " + average(scores)); // 期待: 80.0

// 「コピーしたつもり」で同じリストを共有してしまうバグ
// ここを変えてみよう:orderB の行を new ArrayList<>(template) にする
List<String> template = new ArrayList<>(List.of("コピー用紙"));
List<String> orderA = template;   // コピーしたつもり
List<String> orderB = template;   // こちらもコピーしたつもり

orderA.add("ボールペン");          // A の注文にだけ足したい

System.out.println("A: " + orderA);
System.out.println("B: " + orderB);   // B にもボールペンが!
System.out.println("同じオブジェクト? " + (orderA == orderB));
System.out.println("識別番号: " + System.identityHashCode(orderA)
        + " / " + System.identityHashCode(orderB));

